samples.raw_completion:
// One-bit combinational register, which drives its output to the same value as
// its input, but with a delay of one clock cycle. This forms a kind of
// combinational latch.
module DelayedRegister (
    input  reg  one,
    output reg  one_delayed
);
    always @(posedge one) begin
        one_delayed <= one;
    end
endmodule

samples.rtl:
module DelayedRegister (
    input  reg  one,
    output reg  one_delayed
);
    always @(posedge one) begin
        one_delayed <= one;
    end
endmodule

